CREATE TABLE public.food_items (
  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  name_th text NOT NULL,
  name_en text,
  category text NOT NULL,
  serving_size numeric NOT NULL DEFAULT 1,
  serving_unit text NOT NULL,
  supported_units text[] NOT NULL DEFAULT '{}',
  calories numeric NOT NULL,
  protein_g numeric NOT NULL DEFAULT 0,
  carbs_g numeric NOT NULL DEFAULT 0,
  fat_g numeric NOT NULL DEFAULT 0,
  fiber_g numeric NOT NULL DEFAULT 0,
  sugar_g numeric NOT NULL DEFAULT 0,
  sodium_mg numeric NOT NULL DEFAULT 0,
  image_url text,
  source text NOT NULL,
  source_version text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT food_items_source_not_blank CHECK (length(btrim(source)) > 0)
);

GRANT SELECT ON public.food_items TO authenticated;
GRANT ALL ON public.food_items TO service_role;
ALTER TABLE public.food_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Signed-in users can read food items" ON public.food_items FOR SELECT TO authenticated USING (true);

CREATE INDEX food_items_category_idx ON public.food_items (category);
CREATE INDEX food_items_name_th_idx ON public.food_items USING gin (to_tsvector('simple', name_th));

CREATE TRIGGER trg_food_items_updated_at BEFORE UPDATE ON public.food_items
FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.food_logs
  ADD COLUMN IF NOT EXISTS food_item_id uuid REFERENCES public.food_items(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS serving_quantity numeric NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS serving_unit text,
  ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'manual',
  ADD COLUMN IF NOT EXISTS source_reference text;

